create extension if not exists pgcrypto;create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,phone text,role text not null default 'customer' check(role in('customer','admin')),created_at timestamptz not null default now());create table if not exists public.categories(id uuid primary key default gen_random_uuid(),name text not null unique,slug text not null unique,description text);create table if not exists public.products(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,category text not null,description text not null default '',price_xof integer check(price_xof is null or price_xof>0),image_url text,stock integer not null default 0 check(stock>=0),is_active boolean not null default false,featured boolean not null default false,created_at timestamptz not null default now());create table if not exists public.orders(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),customer_name text not null,phone text not null,address text not null,city text not null,total_xof integer not null check(total_xof>=0),status text not null default 'pending' check(status in('pending','confirmed','preparing','shipped','delivered','cancelled')),payment_status text not null default 'pending',created_at timestamptz not null default now());create table if not exists public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,product_id uuid references public.products(id),product_name text not null,quantity integer not null check(quantity>0),unit_price_xof integer not null,line_total_xof integer not null);alter table public.profiles enable row level security;alter table public.categories enable row level security;alter table public.products enable row level security;alter table public.orders enable row level security;alter table public.order_items enable row level security;create policy "Read own profile" on public.profiles for select to authenticated using((select auth.uid())=id);create policy "Update own profile" on public.profiles for update to authenticated using((select auth.uid())=id) with check((select auth.uid())=id);create policy "Public category read" on public.categories for select to anon,authenticated using(true);create policy "Public active product read" on public.products for select to anon,authenticated using(is_active=true);create policy "Read own orders" on public.orders for select to authenticated using((select auth.uid())=user_id);create policy "Create own orders" on public.orders for insert to authenticated with check((select auth.uid())=user_id);create policy "Read own order lines" on public.order_items for select to authenticated using(exists(select 1 from public.orders o where o.id=order_id and o.user_id=(select auth.uid())));grant select on public.categories,public.products to anon,authenticated;grant select,update on public.profiles to authenticated;grant select,insert on public.orders to authenticated;grant select on public.order_items to authenticated;create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''));return new;end;$$;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();